using System;using System.IO;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {public sealed class WebImportTests {
 [Test]public void OriginalSourceTransferPreservesEveryByteAndNativeReload(){string raw=File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/WebImportReferenceCase.json"));var transfer=JsonUtility.FromJson<WebTransfer>(raw);var s=UnityWebImport.Validate(raw);Assert.That(s.Web.original,Is.EqualTo(transfer.original));Assert.That(s.Web.normalized,Is.EqualTo(transfer.normalized));Assert.That(s.Story.target,Is.EqualTo("name"));var codec=new UnitySaveCodec();var reload=codec.Decode(codec.Encode(StateData.From(s)),AtomicSaveStore.Version).ToState();Assert.That(reload.Web.original,Is.EqualTo(transfer.original));Assert.That(reload.Credits.CompareTo(s.Credits),Is.Zero);Assert.Throws<NotSupportedException>(()=>UnityWebImport.Validate(raw.Insert(1,"\"unknown\":1,")));}
 [Test]public void OriginalAndNormalizedEconomyMustMatchNativeTransfer(){string raw=File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/WebImportReferenceCase.json"));var transfer=JsonUtility.FromJson<WebTransfer>(raw);var data=new UnitySaveCodec().Decode(transfer.payload);data.credits=ScientificNumber.From(51).ToData();transfer.payload=new UnitySaveCodec().Encode(data);Assert.Throws<FormatException>(()=>UnityWebImport.Validate(JsonUtility.ToJson(transfer)));}
}}
